/**
 * fangraphs-data.ts
 *
 * Typed import module for FanGraphs JSON assets bundled with the extension.
 * Assets are generated by: npx tsx packages/extension/scripts/convert-fangraphs-csvs.ts
 *
 * These are static imports — no network calls required. Suitable for offline draft use.
 */

import fgLeaderboardHitters from "../assets/fangraphs-leaderboard-hitters.json";
import fgLeaderboardPitchers from "../assets/fangraphs-leaderboard-pitchers.json";
import fgAuctionHitters from "../assets/fangraphs-auction-hitters.json";
import fgAuctionPitchers from "../assets/fangraphs-auction-pitchers.json";

// ============================================================
// Interfaces
// ============================================================

/**
 * FanGraphs leaderboard projection for a hitter.
 * Source: fangraphs-leaderboard-projections-7.csv
 */
export interface FgHitterProjection {
  name: string;
  team: string;
  mlbamId: number;
  fgId: string;
  HR: number;
  R: number;
  RBI: number;
  SB: number;
  AVG: number;
  OPS: number;
  AB: number;
  H: number;
  BB: number;
  HBP: number;
  SF: number;
  TB: number;
  PA: number;
}

/**
 * FanGraphs leaderboard projection for a pitcher.
 * Source: fangraphs-leaderboard-projections-8.csv
 *
 * IMPORTANT: Pitcher H/BB/HR are stored as HA/BBA/HRA to avoid collision with
 * hitter stat keys when used with calculateFinalRate from shared formulas.
 * The WHIP formula uses HA (hits allowed) and BBA (walks allowed).
 */
export interface FgPitcherProjection {
  name: string;
  team: string;
  mlbamId: number;
  fgId: string;
  W: number;
  SV: number;
  HLD: number;
  ERA: number;
  WHIP: number;
  SO: number;
  IP: number;
  HA: number;    // Hits allowed (renamed from H)
  ER: number;
  BBA: number;   // Walks allowed (renamed from BB)
  QS: number;
  HRA: number;   // Home runs allowed (renamed from HR)
}

/**
 * FanGraphs auction calculator value for a hitter.
 * Source: fangraphs-auction-calculator.csv
 */
export interface FgAuctionHitter {
  name: string;
  team: string;
  pos: string;
  mlbamId: number;
  fgId: string;
  dollars: number;
  mAVG: number;
  mRBI: number;
  mR: number;
  mSB: number;
  mOPS: number;
  pts: number;
}

/**
 * FanGraphs auction calculator value for a pitcher.
 * Source: fangraphs-auction-calculator-2.csv
 */
export interface FgAuctionPitcher {
  name: string;
  team: string;
  pos: string;
  mlbamId: number;
  fgId: string;
  dollars: number;
  mW: number;
  mSV: number;
  mERA: number;
  mWHIP: number;
  mSO: number;
  pts: number;
  ip: number;
}

// ============================================================
// Typed data exports
// ============================================================

export const fgLeaderboardHittersData = fgLeaderboardHitters as FgHitterProjection[];
export const fgLeaderboardPitchersData = fgLeaderboardPitchers as FgPitcherProjection[];
export const fgAuctionHittersData = fgAuctionHitters as FgAuctionHitter[];
export const fgAuctionPitchersData = fgAuctionPitchers as FgAuctionPitcher[];
